python3 - <<'EOF'
import re, glob, statistics, json
reports={}
for f in sorted(glob.glob('reports/*.md')):
    t=open(f).read()
    wid=re.search(r'^# .*?— (W\d+)',t,re.M).group(1)
    m=re.search(r'^(?:Region: (\w+)|This site sits in the (\w+) region\.|A (\w+)-region site\.)$',t,re.M)
    region=next(x for x in m.groups() if x)
    mm=re.search(r'^(?:Site manager: |Managed by |(.+?) runs the floor here\.)(.*)$',t,re.M)
    manager=(mm.group(1) or mm.group(2)).rstrip('.')
    yr=int(re.search(r'(?:Opened in|Operating since|Commissioned) (\d{4})',t).group(1))
    stock={}
    for line in t.splitlines():
        if line.startswith('- ') and 'SKU-' in line:
            sku=re.search(r'SKU-[A-Z0-9]+',line).group()
            n=int(re.search(r'\d+',line).group())
            stock[sku]=n
    reports[wid]={'region':region,'manager':manager,'year':yr,'stock':stock}
print('n=',len(reports))
for k,v in reports.items(): print(k,v['region'],v['year'],repr(v['manager']),v['stock'])
print()
q1=sum(v['stock'].get('SKU-A9',0) for v in reports.values())
c3={k:v['stock'].get('SKU-C3',0) for k,v in reports.items()}
print('q1',q1)
print('q2',max(c3,key=lambda k:(c3[k],k)),{k:v for k,v in c3.items() if v>=800

